datatype Node = Node(value: int, next: Option<Node>)

function method SumEvenNumbers(list: Option<Node>): int
  decreases list
{
  match list
    case None => 0
    case Some(node) =>
      (if node.value % 2 == 0 then node.value else 0) + SumEvenNumbers(node.next)
}

predicate ValidList(list: Option<Node>)
  decreases list
{
  match list
    case None => true
    case Some(node) => ValidList(node.next)
}

predicate RegionContains(r: set<Node>, list: Option<Node>)
  decreases list
{
  match list
    case None => true
    case Some(node) => node in r && RegionContains(r, node.next)
}

predicate ConnectedInRegion(r: set<Node>, n1: Node, n2: Node)
{
  n1 in r && n2 in r &&
  (exists path: Option<Node> :: 
    ValidList(path) && RegionContains(r, path) &&
    match path
      case Some(start) => start == n1 && 
        (exists endNode: Node :: GetLast(path) == Some(endNode) && endNode == n2)
      case None => false
    end)
}

function method GetLast(list: Option<Node>): Option<Node>
  decreases list
{
  match list
    case None => None
    case Some(node) => match node.next
      case None => Some(node)
      case Some(_) => GetLast(node.next)
    end
}

method ReverseInPlace(list: Option<Node>) returns (newList: Option<Node>)
  requires ValidList(list)
  ensures ValidList(newList)
  ensures SumEvenNumbers(list) == SumEvenNumbers(newList)
  ensures forall n: Node :: n in Nodes(list) <==> n in Nodes(newList)
  ensures forall n1: Node, n2: Node :: 
    n1 in Nodes(list) && n2 in Nodes(list) && 
    ConnectedInRegion(Nodes(list), n1, n2) ==>
    ConnectedInRegion(Nodes(newList), n2, n1)
{
  var prev: Option<Node> := None;
  var current: Option<Node> := list;
  ghost var region: set<Node> := Nodes(list);
  ghost var originalConnections: set<(Node, Node)> := AllConnections(list);

  while current != None
    invariant ValidList(current)
    invariant ValidList(prev)
    invariant forall n: Node :: n in Nodes(current) || n in Nodes(prev) <==> n in region
    invariant SumEvenNumbers(list) == SumEvenNumbers(current) + SumEvenNumbers(prev)
    invariant forall n1: Node, n2: Node :: 
      (n1, n2) in originalConnections && n1 in Nodes(prev) && n2 in Nodes(prev) ==>
      ConnectedInRegion(region, n2, n1)
    invariant forall n1: Node, n2: Node :: 
      (n1, n2) in originalConnections && n1 in Nodes(current) && n2 in Nodes(current) ==>
      ConnectedInRegion(region, n1, n2)
    decreases |Nodes(current)|
  {
    match current {
      case None => 
      case Some(node) =>
        var next := node.next;
        node.next := prev;
        prev := Some(node);
        current := next;

        ghost var oldPrevNodes := Nodes(prev);
        ghost var oldCurrentNodes := Nodes(current);

        assert forall n: Node :: n in oldPrevNodes ==> n in region;
        assert forall n: Node :: n in oldCurrentNodes ==> n in region;
    }
  }

  newList := prev;
}

function method Nodes(list: Option<Node>): set<Node>
  decreases list
{
  match list
    case None => {}
    case Some(node) => {node} + Nodes(node.next)
}

function method AllConnections(list: Option<Node>): set<(Node, Node)>
  decreases list
{
  match list
    case None => {}
    case Some(node) => match node.next
      case None => {}
      case Some(nextNode) => {(node, nextNode)} + AllConnections(node.next)
